    CONSTRAINT invoices_status_check CHECK ((status = ANY (ARRAY['Draft'::text, 'Sent'::text, 'Partially Paid'::text, 'Paid'::text, 'Overdue'::text, 'Void'::text]))),
    CONSTRAINT invoices_subtotal_check CHECK ((subtotal >= (0)::numeric)),
